 80	\begin{definition}[Single-basis marginals of the polynomial-pair measurement]\label{def:s-w-marginals}
 81		\lean{MIPStarRE.QPBT.GlobalPairWitness.marginalPoly}
 82		\leanok
 83		\uses{lem:qld-4-7}
 84		Let $\{\hat{S}_{g_X,g_Z}\}$ be the projective measurement of Lemma~\ref{lem:qld-4-7}. For every $g \in \mathrm{ideg}_{d,m}(\F_q)$ define
 85		\[
 86			\hat{S}^X_g = \sum_{g_Z} \hat{S}_{g,g_Z}
 87			\qquad \text{and} \qquad
 88			\hat{S}^Z_g = \sum_{g_X} \hat{S}_{g_X,g}\;,
 89		\]
 90		the sums ranging over $\mathrm{ideg}_{d,m}(\F_q)$.
 91	\end{definition}
