100	\begin{definition}[Pauli dot-product projectors]\label{def:tau-dot-product-projector}
101		\lean{MIPStarRE.QPBT.tauDotProj}
102		\leanok
103		\uses{def:generalized-pauli}
104		For $W \in \{X,Z\}$ and $h \in \F_q^{M}$ let $\tau^W_h$ denote the projector corresponding to measuring $(\C^q)^{\ot M}$ in the $W$ basis and obtaining the outcome $h$ (Definition~\ref{def:generalized-pauli}). For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^{M}$, and $a \in \F_q$, define the operator
105		\begin{equation}\label{eq:def-tauwu}
106			\tau^{W}_{a}(\tilde{u}) = \sum_{h \in \F_q^{M} \,:\, h \cdot \tilde{u} = a} \tau^W_{h}\;.
107		\end{equation}
108	\end{definition}
