140	\begin{definition}[Pulled-apart Pauli observables]\label{def:tilde-w-observables}
141		\lean{MIPStarRE.QPBT.tildeObs}
142		\leanok
143		\uses{def:tilde-m-measurement, def:dual-self-dual-normal-basis, def:binary-representation, def:subfield-trace}
144		Let $\{e_j\}_{j \in \{0,\ldots,t-1\}}$ be the self-dual normal basis for $\F_q$ over $\F_2$ (Definition~\ref{def:dual-self-dual-normal-basis}) that is fixed once and for all in Definition~\ref{def:binary-representation}, and let $\tr = \tr_{q \to 2} \colon \F_q \to \F_2$ be the subfield trace. For all $W \in \{X,Z\}$, $\tilde{u} \in \F_q^M$, and $j \in \{0,\ldots,t-1\}$ define the operator
145		\begin{equation}\label{eq:def-tildewj}
146			\tilde{W}^j(\tilde{u}) = \sum_{a \in \F_q} (-1)^{\tr(e_j a)} \, \tilde{M}_a^{W,\tilde{u}}\;,
147		\end{equation}
148		acting on the same registers as $\tilde{M}^{W,\tilde{u}}_a$.
149	\end{definition}
